import{_ as o,o as i,c as t,a2 as a}from"./chunks/framework.BN2sqjC1.js";const g=JSON.parse('{"title":"ADR-0036 — Verifiche locali al posto di un servizio di CI","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0036-verifiche-locali-senza-ci.md","filePath":"adr/0036-verifiche-locali-senza-ci.md"}'),c={name:"adr/0036-verifiche-locali-senza-ci.md"};function r(n,e,d,s,l,u){return i(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="adr-0036-—-verifiche-locali-al-posto-di-un-servizio-di-ci" tabindex="-1">ADR-0036 — Verifiche locali al posto di un servizio di CI <a class="header-anchor" href="#adr-0036-—-verifiche-locali-al-posto-di-un-servizio-di-ci" aria-label="Permalink to &quot;ADR-0036 — Verifiche locali al posto di un servizio di CI&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata</td></tr><tr><td><strong>Recepito in</strong></td><td><code>Specifications.md</code> v1.2 (2026-11-02): §2.3.3, §2.7.3, §3.7, §3.8.7, §4.1, §4.3, §4.5, Appendice A, C.2 (Appendice C.4)</td></tr><tr><td><strong>Data</strong></td><td>2026-11-01</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>§6 (qualità, CI); ADR-0029/0030 (parità web), ADR-0031 (pipeline di rilascio), ADR-0032 (Task)</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td>sì: lo spec e la roadmap presuppongono una CI bloccante su ogni push (conformance, parità) → la parte su CI va riscritta come in questo ADR</td></tr></tbody></table><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>Con M10-WP3/WP4 sono stati rimossi <code>ci.yml</code>, <code>security.yml</code> e <code>verify.yml</code> (commit <code>9c773e1</code>, <code>4631447</code>). L&#39;unico workflow rimasto, <code>.github/workflows/release.yml</code>, parte sui tag e costruisce e pubblica immagine, chart e installer senza eseguire nessun controllo.</p><p>Molti documenti (README, <code>docs/dev-setup.md</code>, <code>docs/web-workbench-parity.md</code>, roadmap, ADR-0030/0031, documenti di sicurezza) descrivono però ancora una CI bloccante. L&#39;analisi del 2026-11-01 ha trovato le conseguenze concrete:</p><ul><li><code>scripts/parity.mjs --check</code> non era richiamato da nessuna parte e, senza i binding generati, usciva con successo;</li><li><code>TestDispatcherMatchesTheGeneratedBindings</code> cercava i binding in <code>apps/desktop/frontend/wailsjs</code> (spostati in <code>packages/workbench/wailsjs</code>) e veniva quindi sempre saltato;</li><li><code>task ci</code> eseguiva solo lint, govulncheck e test: niente typecheck TypeScript, niente test del core in WASM, niente controllo del codice generato, e su Linux o su un clone pulito falliva per motivi d&#39;ambiente (tag <code>webkit2_41</code>, <code>frontend/dist</code> mancante).</li></ul><p>Il proprietario del progetto ha scelto di non ripristinare un servizio di CI e di rendere ufficiali le verifiche locali.</p><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><ol><li><strong>Nessun servizio di CI.</strong> <code>release.yml</code> resta l&#39;unico workflow e non esegue controlli. Le verifiche si fanno in locale.</li><li><strong><code>task ci</code> è il cancello ufficiale.</strong> Va eseguito, con esito verde, prima di ogni merge su <code>main</code> e prima di creare un tag di rilascio. Comprende: <ul><li><code>lint</code> (golangci-lint, ESLint, Prettier);</li><li><code>typecheck</code> (tutti i pacchetti TypeScript);</li><li><code>vuln</code> (govulncheck);</li><li><code>test-go</code> (con <code>-race</code>, il tag <code>webkit2_41</code> dove serve, e <code>MEMOBRAIN_REQUIRE_BINDINGS=1</code>, per cui il test dispatcher/binding fallisce invece di essere saltato);</li><li><code>test-ts</code>, <code>conformance</code>, <code>test-wasm</code> (core Go in WebAssembly);</li><li><code>parity</code> (<code>scripts/parity.mjs --check</code>, che ora fallisce se i binding mancano);</li><li><code>check-gen</code> (fallisce se <code>task gen</code> modifica l&#39;albero).</li></ul></li><li><strong>Suite lente, da eseguire quando si tocca l&#39;area relativa e comunque prima di un rilascio:</strong> <code>task test-integration</code> (cloud, Docker), <code>task test-desktop-e2e</code> (sync a due dispositivi), <code>task e2e</code> e <code>yarn workspace @memobrain/web e2e:workbench-ui</code> (Playwright), <code>e2e:cloud</code> ed <code>e2e:security</code> (stack di sviluppo). L&#39;elenco è in <code>docs/dev-setup.md</code>.</li><li><strong>Documentazione:</strong> README, <code>dev-setup.md</code>, <code>web-workbench-parity.md</code>, roadmap, documenti di rilascio e di sicurezza vanno corretti: non si promette più una CI, si rimanda a questo ADR e a <code>task ci</code>.</li></ol><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong>Ripristinare GitHub Actions (<code>ci.yml</code> su push/PR, job notturno per gli e2e):</strong> è la protezione più forte, ma è stata scartata dal proprietario per costo e manutenzione dei runner. Resta un&#39;opzione se il progetto cresce a più contributori: basterebbe un workflow che esegue <code>task ci</code>.</li><li><strong>Controlli dentro <code>release.yml</code>:</strong> avrebbe bloccato solo i rilasci, non i merge, e allungato una pipeline già lenta (build multi-piattaforma). Scartata per ora.</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><ul><li><strong>Positive:</strong> nessun runner da mantenere. <code>task ci</code> diventa ermetico e completo: copre anche typecheck, core WASM, parità e codice generato, che prima non verificava nessuno.</li><li><strong>Negative:</strong> la protezione dipende dalla disciplina di chi fa merge e rilasci. Una regressione può arrivare su <code>main</code> se <code>task ci</code> non viene eseguito.</li><li><strong>Da rivedere:</strong> quando ci saranno più contributori, o dopo una regressione arrivata in release, valutare un <code>ci.yml</code> minimo che esegua <code>task ci</code>.</li></ul>',13)])])}const m=o(c,[["render",r]]);export{g as __pageData,m as default};
